package com.ftk.tpip.control.application.catalog;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import com.ftk.tpip.catalog.domain.model.*;import com.ftk.tpip.control.application.provider.CanonicalJsonService;import org.springframework.stereotype.Component;
@Component public class CanonicalSchemaContentCanonicalizer{private static final String DRAFT="https://json-schema.org/draft/2020-12/schema";private final ObjectMapper mapper;private final CanonicalJsonService json;public CanonicalSchemaContentCanonicalizer(ObjectMapper mapper,CanonicalJsonService json){this.mapper=mapper;this.json=json;}public CanonicalSchemaContent canonicalize(SchemaStandard standard,JsonNode schema,JsonNode example,CompatibilityMode mode){if(schema==null||schema.isNull()||!schema.isObject())throw new IllegalArgumentException("schemaDocument must be a JSON object");JsonNode declaration=schema.get("$schema");if(declaration!=null&&(!declaration.isTextual()||!DRAFT.equals(declaration.textValue())))throw new IllegalArgumentException("schemaDocument.$schema must be "+DRAFT);String canonicalSchema=json.canonicalString(schema);String canonicalExample=json.canonicalString(example);if(canonicalSchema.length()>1_048_576)throw new IllegalArgumentException("schemaDocument must not exceed 1 MiB");if(canonicalExample!=null&&canonicalExample.length()>1_048_576)throw new IllegalArgumentException("exampleDocument must not exceed 1 MiB");ObjectNode content=mapper.createObjectNode();content.put("schemaStandard",standard.name());content.set("schemaDocument",json.canonicalNode(schema));if(example!=null&&!example.isNull())content.set("exampleDocument",json.canonicalNode(example));content.put("compatibilityMode",mode.name());return new CanonicalSchemaContent(canonicalSchema,canonicalExample,json.sha256(json.write(json.canonicalNode(content))));}}
